<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Database\DB;use StudPulse\Domain\{Access,Input,LessonLibrary};use StudPulse\Security\Auth;final class NotesController{public function detail(Auth$a,string$id):array{$note=DB::one('SELECT * FROM personal_notes WHERE id=? AND owner_user_id=?',[$id,$a->user['id']]);if(!$note){throw new ApiError(404,'NOT_FOUND','Заметка не найдена');}$note['attachments']=DB::all('SELECT m.id,m.title FROM note_materials nm JOIN materials m ON m.id=nm.material_id WHERE nm.note_id=? AND m.owner_user_id=? AND m.visibility=\'private\' AND m.deleted_at IS NULL',[$id,$a->user['id']]);return$note;}public function attach(Auth$a,Request$r,string$id):array{$a->require('materials:write');$this->detail($a,$id);$m=Access::material($a,Input::id($r->body['materialId']??null)??'',true);if($m['visibility']!=='private'){throw new ApiError(422,'PRIVATE_REQUIRED','Для личной заметки используйте личный материал');}DB::run('INSERT IGNORE INTO note_materials(note_id,material_id) VALUES(?,?)',[$id,$m['id']]);return['attached'=>true];}public function list(Auth$a):array{[$limit,$cursor]=Input::page();$p=[$a->user['id']];$w='';if($cursor){$w.=' AND id>?';$p[]=$cursor;}if(isset($_GET['lessonRef'])){$lesson=LessonLibrary::resolve($a,Input::text($_GET,'lessonRef',3000));if(!$lesson['id'])return['items'=>[],'nextCursor'=>null];$w.=' AND meeting_id=?';$p[]=$lesson['id'];}if(!empty($_GET['subject'])){$w.=' AND subject_id=?';$p[]=Input::id($_GET['subject']);}if(!empty($_GET['q'])){$w.=' AND (title LIKE ? OR body LIKE ?)';$q='%'.Input::text($_GET,'q',100).'%';array_push($p,$q,$q);}$rows=DB::all('SELECT * FROM personal_notes WHERE owner_user_id=?'.$w.' ORDER BY id LIMIT '.($limit+1),$p);$more=count($rows)>$limit;if($more){array_pop($rows);}return['items'=>$rows,'nextCursor'=>$more?end($rows)['id']:null];}public function save(Auth$a,Request$r,?string$id=null):array{$existing=$id?DB::one('SELECT * FROM personal_notes WHERE id=? AND owner_user_id=?',[$id,$a->user['id']]):null;if($id&&!$existing){throw new ApiError(404,'NOT_FOUND','Заметка не найдена');}$sid=Input::id($r->body['subjectId']??null);$mid=Input::id($r->body['meetingId']??null);$s=$sid&&$existing&&$sid===$existing['subject_id']?['id'=>$sid]:Access::subject($a,$sid);if(!$id&&isset($r->body['lessonRef'])){$m=LessonLibrary::resolve($a,Input::text($r->body,'lessonRef',3000),true);}else{$m=$mid&&$existing&&$mid===$existing['meeting_id']?['id'=>$mid,'subject_id'=>$existing['subject_id']]:Access::meeting($a,$mid);}if($s&&$m&&$s['id']!==$m['subject_id']){throw new ApiError(422,'SUBJECT_MISMATCH','Предмет и занятие не совпадают');}$title=Input::text($r->body,'title');$body=Input::text($r->body,'body',50000,false);if($id){if(!DB::one('SELECT id FROM personal_notes WHERE id=? AND owner_user_id=?',[$id,$a->user['id']])){throw new ApiError(404,'NOT_FOUND','Заметка не найдена');}if(!DB::run('UPDATE personal_notes SET title=?,body=?,subject_id=?,meeting_id=?,revision=revision+1,updated_at=UTC_TIMESTAMP(6) WHERE id=? AND owner_user_id=? AND revision=?',[$title,$body,$s['id']??$m['subject_id']??null,$m['id']??null,$id,$a->user['id'],Input::revision($r->body)])->rowCount()){throw new ApiError(409,'VERSION_CONFLICT','Заметка изменена на другом устройстве. Скопируйте свой текст перед обновлением.');}}else{$id=DB::id();DB::run('INSERT INTO personal_notes(id,owner_user_id,title,body,subject_id,meeting_id) VALUES(?,?,?,?,?,?)',[$id,$a->user['id'],$title,$body,$s['id']??$m['subject_id']??null,$m['id']??null]);}return DB::one('SELECT * FROM personal_notes WHERE id=? AND owner_user_id=?',[$id,$a->user['id']]);}public function delete(Auth$a,string$id):array{if(!DB::run('DELETE FROM personal_notes WHERE id=? AND owner_user_id=?',[$id,$a->user['id']])->rowCount()){throw new ApiError(404,'NOT_FOUND','Заметка не найдена');}return['deleted'=>true];}public function share(Auth$a,Request$r,string$id):array{$a->require('materials:write');$note=DB::one('SELECT * FROM personal_notes WHERE id=? AND owner_user_id=?',[$id,$a->user['id']]);if(!$note){throw new ApiError(404,'NOT_FOUND','Заметка не найдена');}if(($r->body['confirmed']??false)!==true){throw new ApiError(422,'CONFIRM_REQUIRED','Подтвердите публикацию отдельной копии для группы');}$m=$a->group();\StudPulse\Integrations\DriveLibrary::requireConnection($a);$meeting=Access::meeting($a,$note['meeting_id']);if($note['subject_id']){Access::subject($a,$note['subject_id']);}$mid=DB::id();DB::run("INSERT INTO materials(id,owner_user_id,group_id,term_id,subject_id,visibility,title,description) VALUES(?,?,?,?,?,'group',?,?)",[$mid,$a->user['id'],$m['group_id'],$m['term_id'],$note['subject_id'],$note['title'],$note['body']]);if($meeting)DB::run('INSERT INTO material_lessons(material_id,meeting_id) VALUES(?,?)',[$mid,$meeting['id']]);return['id'=>$mid,'message'=>'Опубликована отдельная копия. Личная заметка остаётся приватной.'];}}